initialize:
return (async () => {
const username = encodeURIComponent(env.get('RABBITMQ_USER') || 'library');
const password = encodeURIComponent(env.get('RABBITMQ_PASSWORD') || 'library');
const host = env.get('RABBITMQ_HOST') || 'rabbitmq';
const exchange = env.get('RABBITMQ_EXCHANGE') || 'library.events';
const queue = env.get('RABBITMQ_QUEUE') || 'library.node-red';

node.status({fill: 'yellow', shape: 'ring', text: 'connecting'});
const connection = await amqp.connect(`amqp://${username}:${password}@${host}:5672/`);
const channel = await connection.createChannel();
await channel.assertExchange(exchange, 'topic', {durable: true});
await channel.assertQueue(queue, {durable: true});
await channel.bindQueue(queue, exchange, 'loan.#');
await channel.prefetch(10);

context.set('connection', connection);
context.set('channel', channel);
node.status({fill: 'green', shape: 'dot', text: `listening: ${queue}`});

await channel.consume(queue, message => {
    if (!message) return;
    try {
        const event = JSON.parse(message.content.toString());
        node.send({payload: event, topic: message.fields.routingKey});
        channel.ack(message);
    } catch (error) {
        node.error(`Invalid event: ${error.message}`);
        channel.nack(message, false, false);
    }
}, {noAck: false});
})();

finalize:
return (async () => {
const channel = context.get('channel');
const connection = context.get('connection');
if (channel) await channel.close();
if (connection) await connection.close();
node.status({});
})();

func:
const client = context.get('client');
const bucket = context.get('bucket');
const event = msg.payload;
const date = new Date(event.occurred_at);
const dayPath = date.toISOString().slice(0, 10).replaceAll('-', '/');
const timestamp = date.toISOString().replaceAll(':', '-');
const action = event.type === 'loan.borrowed' ? 'Book borrowed' : 'Book returned';
const bookTitle = event.data.book_title || 'Unknown book';
const bookAuthor = event.data.book_author || 'Unknown author';
const memberName = event.data.member_name || 'Unknown member';
const slug = value => value.normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-|-$/g, '').slice(0, 60) || 'unknown';
const fileBase = `${event.type}-${slug(bookTitle)}-${slug(memberName)}`;
const objectName = `loan-reports/${dayPath}/${timestamp}-${fileBase}.pdf`;

const doc = new PDFDocument({size: 'A4', margin: 56, info: {Title: `Library receipt - ${bookTitle}`}});
const chunks = [];
doc.on('data', chunk => chunks.push(chunk));
doc.on('error', error => node.error(`PDF creation failed: ${error.message}`, msg));
doc.on('end', async () => {
    try {
        const body = Buffer.concat(chunks);
        await client.putObject(bucket, objectName, body, body.length, {
            'Content-Type': 'application/pdf',
            'Content-Disposition': `inline; filename=\"${fileBase}.pdf\"`
        });
        msg.archive = {bucket, objectName, contentType: 'application/pdf'};
        node.status({fill: 'green', shape: 'dot', text: objectName});
        node.send(msg);
        node.done();
    } catch (error) {
        node.error(`MinIO upload failed: ${error.message}`, msg);
        node.done();
    }
});

doc.fontSize(22).fillColor('#1f2937').text('Library Cloud', {align: 'center'});
doc.moveDown(0.4).fontSize(15).fillColor('#374151').text('Loan activity receipt', {align: 'center'});
doc.moveDown(2);
doc.fontSize(12).fillColor('#111827');
doc.text(`Action: ${action}`);
doc.moveDown(0.5).text(`Date: ${date.toLocaleString('en-GB', {timeZone: 'Europe/Athens'})}`);
doc.moveDown(0.5).text(`Book: ${bookTitle}`);
doc.moveDown(0.5).text(`Author: ${bookAuthor}`);
doc.moveDown(0.5).text(`Member: ${memberName}`);
doc.moveDown(2);
doc.fontSize(9).fillColor('#6b7280').text('Automatically generated from a RabbitMQ event and archived by Node-RED in MinIO.');
doc.end();
return;

initialize:
return (async () => {
const endPoint = env.get('MINIO_HOST') || 'minio';
const port = Number(env.get('MINIO_PORT') || 9000);
const accessKey = env.get('MINIO_ROOT_USER') || 'library';
const secretKey = env.get('MINIO_ROOT_PASSWORD') || 'library-minio';
const bucket = env.get('MINIO_AUDIT_BUCKET') || 'library-audit';
const client = new Minio.Client({endPoint, port, useSSL: false, accessKey, secretKey});
if (!(await client.bucketExists(bucket))) await client.makeBucket(bucket);
context.set('client', client);
context.set('bucket', bucket);
node.status({fill: 'green', shape: 'dot', text: `bucket: ${bucket}`});
})();
